revision.text:
/* subpage tree on portal pages */
.folder-nav {
    background: var(--folder-nav-bg, #f2f3f9);
    padding: 1em;

    .folder-nav .subpagelist > ul {
        margin-top: 1em;
        margin-bottom: 1em;
        column-gap: 1.5rem;
    }
    .folder-nav.col2 .subpagelist > ul {
        column-count: 2;
    }
    .folder-nav.col3 .subpagelist > ul {
        column-count: 3;
    }

    .folder-nav.avoid .subpagelist li {
        break-inside: avoid;
    }

    /* avoid empty space if there are no subpages: */
    .folder-nav .default {
        display: none;
        line-height: 0;
        overflow: hidden;
    }

    .bi.prefix::before {
        content: "\f228";
        font-size: 1.2em;
        vertical-align: -0.22em !important;
        margin-right: 0.2em;
    }

    .byline {
        margin-bottom: 0.8em;
    }

    .byline.prefixicon {
        margin-left: 1.8em;
    }

    .byline.neutral {
        color:#747474 !important;
    }
}

.recently-updated-icon::before {
    font-size: 1.2em;
    vertical-align: -0.22em;
    margin-right: 0.2em;
}

.recently-updated-byline {
    margin-bottom: 0.8em;
    margin-left: 1.8em;
    color: #747474;
}
